from pathlib import Path
import json,html,re
R=Path(__file__).resolve().parent.parent
I=json.loads((R/'source/icons.json').read_text())
def ic(n):return I[n]
def img(n,alt,cls=''):return f'<img src="../assets/{n}.png" alt="{html.escape(alt)}" class="{cls}">'
def a(s,t,cls=''):
 plain=re.sub('<[^>]+>','',t).strip()
 labels={'03-collection':'Search Trailmark products','12-profile':'Your Trailmark account','07-cart':'Cart,3 items','04-product-main':'View Rally68 equipment','product-shuttles':'View Court Nylon3 shuttles','product-sleeve':'View Court sleeve'}
 label=labels.get(s,'Open product details') if ('<svg' in t and ('iconlabel' in t or not plain or plain.isdigit())) else None
 attr=' aria-label="'+label+'"' if label else ''
 return f'<a href="{s}.html" class="{cls}"{attr}>{t}</a>' 
def btn(s,t,secondary=False):return a(s,t,'button'+(' secondary' if secondary else ''))
def field(label,val='',full=False,invalid='',placeholder='',kind='text',readonly=False):
 ident=label.lower().replace(' ','-').replace('/','-')
 return f'<div class="field {"full" if full else ""} {"invalid" if invalid else ""}"><label for="{ident}">{label}</label><input id="{ident}" type="{kind}" value="{html.escape(val)}" placeholder="{placeholder}" {"readonly" if readonly else ""} {"aria-invalid=true aria-describedby="+ident+"-error" if invalid else ""}>{f"<span class=error-text id={ident}-error>{invalid}</span>" if invalid else ""}</div>'
def notice(t,kind='',icon='CircleHelp'):return f'<div class="notice {kind}">{ic(icon)}<p>{t}</p></div>'
def quantity(n=1):return f'<div class="quantity" aria-label="Quantity"><button type="button" data-quantity="-1" aria-label="Decrease quantity">{ic("Minus")}</button><span>{n}</span><button type="button" data-quantity="1" aria-label="Increase quantity">{ic("Plus")}</button></div>'
def header():return f'''<div class="announcement">A little more play. A little less guesswork.</div><header class="header"><div class="wrap head"><button class="menu" aria-label="Open navigation" aria-expanded="false" data-menu>{ic('Menu')}</button>{a('01-home-top','<span class="mark"></span>TRAILMARK','wordmark')}<nav class="nav" aria-label="Shop">{a('03-collection','Activities')}{a('03-collection','Equipment')}{a('attribute-model','Clothing')}{a('05-product-specs','Guides')}{a('06-product-continuation','Support')}</nav><div class="util">{a('03-collection',ic('Search')+'<span class="iconlabel">Search</span>')}{a('12-profile',ic('UserRound'),'account-util')}{a('07-cart',ic('ShoppingBag')+'<span class="small">3</span>')}</div></div><nav class="mobile-menu" aria-label="Mobile shop">{a('03-collection','Activities & equipment')}{a('attribute-model','Clothing')}{a('05-product-specs','Guides')}{a('12-profile','Your account')}</nav></header>'''
def crumb(*parts):return '<div class="wrap"><nav class="crumb" aria-label="Breadcrumb">'+f'{a("01-home-top","Home")}{ic("ChevronRight")}' +(ic('ChevronRight').join(parts))+'</nav></div>'
def footer():return f'''<footer class="footer"><div class="wrap"><div class="foot-grid"><div><div class="wordmark">TRAILMARK</div><p style="margin-top:18px">For the games you make time for.<br>Recreational gear, with the details that matter.</p></div><div><h4>Explore</h4>{a('03-collection','Badminton')}{a('03-collection','Everyday movement')}{a('attribute-model','Clothing')}</div><div><h4>Know your gear</h4>{a('05-product-specs','Measurements')}{a('06-product-continuation','Care & conditions')}{a('06-product-continuation','Returns & support')}</div><div><h4>Your Trailmark</h4>{a('12-profile','Account')}{a('13-orders','Orders')}{a('15-addresses','Addresses')}</div></div><div class="foot-note"><span>© 2026 Trailmark · Fictional design fixture</span><span>India / INR ₹ &nbsp; · &nbsp; Privacy &nbsp; · &nbsp; Terms</span><span>Commerce by LetBuyy</span></div></div></footer>'''
products=[dict(name='Rally 68 badminton racket',image='racket',type='BADMINTON / RACKET',facts=['68 cm length','88 g unstrung'],price='₹2,490'),dict(name='Court Nylon 3 shuttles',image='shuttles',type='BADMINTON / SHUTTLES',facts=['3 pieces / tube','Nylon skirt'],price='₹490'),dict(name='Court single-racket sleeve',image='sleeve',type='BADMINTON / STORAGE',facts=['72 × 24 cm exterior','Single compartment'],price='₹690')]
def card(p):return f'''<article class="card">{a('04-product-main' if p['image']=='racket' else 'product-'+p['image'],img(p['image'],p['name']),'photo')}<div class="card-body"><div class="type">{p['type']}</div><h3>{a('04-product-main' if p['image']=='racket' else 'product-'+p['image'],p['name'])}</h3><div class="facts">{''.join('<span>'+x+'</span>'for x in p['facts'])}</div><div class="card-bottom"><span>{p['price']}</span>{a('04-product-main' if p['image']=='racket' else 'product-'+p['image'],ic('ArrowUpRight'))}</div></div></article>'''
def cards():return '<div class="gear-grid">'+''.join(card(p) for p in products)+'</div>'
def context():return f'<div class="wrap contextbar"><div><span class="eyebrow">RALLY 68</span> &nbsp; Grip 84 mm · Forest · ₹2,490</div>{a("04-product-main","Back to selection "+ic("ArrowRight"),"textlink")}</div>'
def mini_lines():return f'''<div class="mini-line">{img('racket','Rally 68, Forest')}<div><strong>Rally 68 racket × 1</strong><p>Forest / Grip 84 mm</p></div><span>₹2,490</span></div><div class="mini-line">{img('shuttles','Court Nylon 3, pack of 3')}<div><strong>Court Nylon 3 × 2</strong><p>3 per tube · 6 shuttles total</p></div><span>₹980</span></div>'''
def summary(checkout=False):
 return '<aside class="summary"><h2>Order summary</h2>'+ (mini_lines() if checkout else '') +f'''<div class="sumrow"><span>Subtotal · 3 items</span><span>₹3,470</span></div><div class="sumrow"><span>{'Standard shipping' if checkout else 'Shipping'}</span><span>{'₹90' if checkout else 'At checkout'}</span></div><div class="sumrow"><span>Discount</span><span>₹0</span></div><div class="sumrow total"><span>{'Total' if checkout else 'Subtotal'}</span><span>{'₹3,560' if checkout else '₹3,470'}</span></div><p class="small">INR · Includes applicable taxes. {'Final fixture quote shown before payment.' if checkout else 'Final shipping and total are confirmed at checkout.'}</p>'''+('' if checkout else btn('08-checkout-address','Continue to checkout '+ic('ArrowRight')))+f'<div class="safe">{ic("LockKeyhole")} Shared LetBuyy checkout</div></aside>'
def checkheader():return f'<header class="checkheader"><div class="checkout-shell checkhead"><div class="checkbrand">TRAILMARK</div><div class="platformmark">{ic("LockKeyhole")} Checkout by LetBuyy</div></div></header>'
def steps(review=False):return f'<nav class="steps" aria-label="Checkout steps">{a("07-cart","Cart")}{ic("ChevronRight")}'+(a('08-checkout-address','Contact & delivery') if review else '<strong>Contact & delivery</strong>')+ic('ChevronRight')+('<strong>Review & pay</strong>'if review else '<span>Review & pay</span>')+'</nav>'
def accountnav(active):
 items=[('12-profile','Overview','UserRound'),('13-orders','Orders','Package'),('15-addresses','Addresses','MapPin')]
 return '<aside class="accountnav"><div class="name">Demo Buyer</div><p>Your Trailmark account</p><nav class="links" aria-label="Your account">'+''.join(a(s,ic(i)+n,'selected'if s==active else '')for s,n,i in items)+a('10-sign-in','Sign out')+'</nav></aside>'
def account(title,desc,content,active='12-profile'):return header()+crumb('Your account')+'<main class="wrap account-grid">'+accountnav(active)+f'<div class="account-main"><h1>{title}</h1><p>{desc}</p>'+content+'</div></main>'+footer()
def identity(title,body,signup=False):
 return f'''<div class="identity-page"><header class="identity-head"><a href="../index.html" class="letbuyy"><img src="../assets/letbuyy-logo.svg" alt="LetBuyy"></a><span class="small">Buyer account</span></header><main class="identity-shell"><div class="identity-context"><div class="eyebrow">ONE LETBUYY BUYER ACCOUNT</div><h2>Your next game.<br>Your familiar account.</h2><p>Use your LetBuyy buyer account to return to Trailmark. Store orders and preferences stay scoped to this shop.</p><div class="destination">{ic('ArrowRight')}<div><strong>Continuing to Trailmark</strong><small>trailmark.example.test / account</small></div></div></div><section class="identity-card"><div class="eyebrow">{'CREATE ACCOUNT / CONTINUE' if signup else 'WELCOME BACK'}</div><h1>{title}</h1>{body}</section></main><footer class="identity-foot"><span>LetBuyy buyer identity · Fictional prototype</span><span>Privacy &nbsp; · &nbsp; Terms &nbsp; · &nbsp; Help</span></footer></div>'''
scenes=[]
def add(id,title,route,content,purpose):scenes.append(dict(id=id,title=title,route=route,purpose=purpose));write(id,title,content)
def write(id,title,content):
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Trailmark visual prototype</title><link rel="stylesheet" href="styles.css"></head><body>{content}<script src="prototype.js"></script></body></html>'''
 (R/'source'/f'{id}.html').write_text(page)
add('01-home-top','Find your kind of play','/ (top)',header()+f'''<main><section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">RECREATION / EVERYDAY MOVEMENT</div><h1>Make room<br>for a game.</h1><p>Start with the activity. Find the gear. Check the measurements. Then get out and enjoy it.</p>{btn('03-collection','Find your equipment '+ic('ArrowRight'))}<div class="hero-meta"><span>01 / Choose an activity</span><span>02 / Know your gear</span></div></div><div class="hero-photo">{img('activity','Two adults enjoying recreational badminton on an outdoor court')}<div class="photo-caption"><span>COURT TIME / BADMINTON</span><span>No score needed.</span></div></div></div><div class="activity-paths">{''.join(f'<a class="path" href="03-collection.html"><span class="num">0{i+1}</span><div><h3>{n}</h3><p>{p}</p></div>{ic("ArrowUpRight")}</a>'for i,(n,p) in enumerate([('Court time','Rackets, shuttles & storage · 3 products'),('Everyday movement','Recreational accessories · Browse by type'),('Clothing','Garment sizes, fit & care · Separate guide')]))}</div></div></section><section class="section"><div class="wrap sectionhead"><div><div class="eyebrow">NEXT / KNOW YOUR EQUIPMENT</div><h2 style="margin-top:12px">Good gear starts with good details.</h2></div>{a('02-home-bottom','Continue exploring '+ic('ArrowRight'),'textlink')}</div></section></main>''','Activity selection before campaign storytelling; homepage first section.')
add('02-home-bottom','Equipment, explained','/ (continuation)',header()+f'''<main><section class="section"><div class="wrap"><div class="sectionhead"><div><div class="eyebrow">COURT TIME / SELECTED EQUIPMENT</div><h1 style="font-size:38px;margin-top:13px">A simple start. Proper details.</h1></div>{a('03-collection','All badminton gear '+ic('ArrowRight'),'textlink')}</div>{cards()}</div></section><section class="section rule"><div class="wrap guide">{img('accessories','Shuttles, towel and a racket sleeve arranged as separate recreational accessories')}<div><div class="eyebrow">THE TRAILMARK FIELD NOTES</div><h2>Choose by the way<br>you want to play.</h2><p>A racket’s length is a measurement. A shirt’s size is a fit label. We keep them separate so you can make a useful choice.</p><div class="guide-steps"><div><b>01 / Activity</b><p>Start with court play, movement or clothing.</p></div><div><b>02 / Measurements</b><p>Check dimensions, weight and named options.</p></div><div><b>03 / Conditions</b><p>Read supplied use and care information.</p></div></div>{a('05-product-specs','Read the equipment guide '+ic('ArrowRight'),'textlink')}</div></div></section><div class="wrap service-grid rule"><div class="service">{ic('Ruler')}<div><h3>Measurements before labels</h3><p>Product-specific units. Unknown facts stay unknown.</p></div></div><div class="service">{ic('Package')}<div><h3>Know what is included</h3><p>Contents are listed on each product page.</p></div></div><div class="service">{ic('CircleHelp')}<div><h3>Support, in plain words</h3><p>Read care and returns before you decide.</p></div></div></div></main>'''+footer(),'Homepage continuation: factual merchandising, education, merchant service and footer.')
add('03-collection','Court time / Badminton','/collections/badminton',header()+crumb('Activities','Badminton')+f'''<main class="wrap"><div class="catalog-intro"><div class="eyebrow">01 / COURT TIME</div><h1>Badminton, your way.</h1><p>Recreational rackets and court accessories. Compare equipment measurements, then choose the actual option that suits your needs.</p><form class="searchbox" action="03-collection.html">{ic('Search')}<input aria-label="Search this shop" name="q" placeholder="Search rackets, shuttles, sleeves"><button aria-label="Search">{ic('ArrowRight')}</button></form></div><nav class="tabs" aria-label="Categories"><a class="selected" href="03-collection.html">All badminton</a>{a('attribute-model','Rackets')}{a('attribute-model','Shuttles')}{a('attribute-model','Storage')}{a('attribute-model','Clothing ↗')}</nav><div class="catalog-layout"><aside class="facets"><div class="eyebrow">NARROW YOUR GEAR</div><div class="facet"><h3>Activity</h3><label><input type="checkbox" checked>Badminton</label><label><input type="checkbox">Everyday movement</label></div><div class="facet"><h3>Equipment type</h3><label><input type="checkbox">Rackets</label><label><input type="checkbox">Shuttles</label><label><input type="checkbox">Storage</label></div><div class="facet"><h3>Racket length</h3><label><input type="checkbox">68 cm</label><p class="small">Applies to rackets only.</p></div><div class="facet"><h3>Compatibility</h3><p class="small">Confirm from each product’s supplied specifications.</p></div></aside><div><div class="resultsbar"><span>3 products</span><div class="filtermobile">{btn('attribute-model',ic('SlidersHorizontal')+' Filter',True)}</div><select class="sort" aria-label="Sort products"><option>Featured</option><option>Price: low to high</option><option>Name: A–Z</option></select></div><div class="chips"><a class="chip" href="attribute-model.html">Badminton {ic('X')}</a></div>{cards()}<nav class="pagination" aria-label="Product pages"><button disabled aria-label="Previous page">{ic('ChevronRight')}</button><a class="active" href="03-collection.html" aria-current="page">1</a><button disabled aria-label="Next page">{ic('ChevronRight')}</button></nav><p style="text-align:center" class="small">Showing all 3 products · You’re up to date.</p>{notice('No matching gear? Keep your activity and clear the equipment filter. '+a('attribute-model','View empty-results example'),'','RotateCcw')}</div></div></main><div style="height:35px"></div>'''+footer(),'Three-column equipment cards; category-scoped units, search, selected activity, sort and pagination. Facets are proposed C contracts.')
add('04-product-main','Rally 68 / Select your grip','/products/rally-68 (selection)',header()+crumb('Badminton','Rackets','Rally 68')+f'''<main class="wrap pdp"><div><div class="gallery-main">{img('racket','Whole Rally 68 badminton racket, forest green frame and dark grip')}</div><div class="gallery-thumbs"><figure>{img('racket','Whole racket view','active')}<figcaption>Whole equipment</figcaption></figure><figure>{img('activity','Recreational court context')}<figcaption>In context</figcaption></figure><figure>{img('accessories','Accessories shown separately')}<figcaption>Not included</figcaption></figure></div></div><div class="pdp-info"><div class="eyebrow">BADMINTON / RECREATIONAL RACKET</div><h1>Rally 68<br>badminton racket</h1><div class="price">₹2,490</div><div class="tax">Price for selected variant · Includes applicable taxes</div><p class="intro">A straightforward racket for casual court sessions. Check the measurements and grip before choosing your equipment.</p><div class="fact-tiles"><div><small>Overall length</small><strong>68 cm</strong></div><div><small>Weight, unstrung</small><strong>88 g</strong></div><div><small>Activity</small><strong style="font-size:15px">Badminton</strong></div></div><div class="selection-label"><span>Color — <strong>Forest</strong></span></div><div class="options"><button class="option selected" aria-pressed="true">Forest {ic('Check')}</button></div><div class="selection-label"><span>Grip circumference — <strong>84 mm</strong></span>{a('05-product-specs','Measurement guide','textlink')}</div><div class="options"><button class="option selected" aria-pressed="true">84 mm {ic('Check')}</button><button class="option" disabled>88 mm<small>Unavailable</small></button></div>{notice('Grip values are circumferences, not clothing sizes. If you are unsure, check an existing racket before choosing.','','Ruler')}<div class="purchase">{quantity()}{btn('07-cart','Add to cart '+ic('ShoppingBag'))}</div><div class="available">{ic('CheckCircle2')} Available in Forest / 84 mm</div><div class="disclosures">{a('05-product-specs','Specifications & conditions '+ic('Plus'),'disclosure')}{a('06-product-continuation','Included contents & care '+ic('Plus'),'disclosure')}{a('06-product-continuation','Shipping & returns '+ic('Plus'),'disclosure')}</div></div></main>''','One equipment SKU, measured grip options, unavailable preserved, price and availability adjacent to purchase.')
add('05-product-specs','Measure first. Choose second.','/products/rally-68 (specifications)',header()+context()+f'''<main><section class="section"><div class="wrap two"><div><div class="eyebrow">RALLY 68 / EQUIPMENT FACTS</div><h1>Measure first.<br>Choose second.</h1><p>Use the exact dimensions for this racket. The technical image illustrates the measurement; the written values are the reference.</p><div class="measurement"><div class="measure-visual">{img('racket','Racket; overall length measured from tip to handle end')}<div class="measure-line"><span>68 cm</span></div></div><p>Overall length: tip of frame to end of handle.<br>Illustration is not to scale. Grip circumference: 84 mm.</p></div>{notice('<strong>Replacement grip compatibility: unconfirmed.</strong><br>No third-party grip fit has been supplied. Check dimensions and ask the merchant before relying on a match.','warning')}</div><div><table class="specs"><caption>Rally 68 · Forest / 84 mm</caption><tbody>{''.join(f'<tr><th scope="row">{k}</th><td>{v}</td></tr>'for k,v in [('Intended activity','Recreational badminton'),('Overall length','68 cm'),('Weight, unstrung','88 g'),('Grip circumference','84 mm · selected variant'),('Frame material','Aluminium'),('Shaft material','Steel'),('Included','1 strung racket'),('Use conditions','Dry court use; store dry'),('String tension range','Not supplied'),('Replacement grip fit','Unconfirmed')])}</tbody></table><p class="small" style="margin-top:17px">Fictional merchant-supplied facts. Photograph is illustrative; no testing or certification is claimed.</p></div></div></section><section class="section rule"><div class="wrap"><div class="eyebrow">CATEGORY MATTERS</div><h2 style="margin-top:12px">Different kit. Different measurements.</h2><div class="model-rule"><div class="panel"><h3>Equipment / Rally 68</h3><p>Length 68 cm · weight 88 g · grip 84 mm.<br>No S / M / L equipment sizes.</p></div><div class="panel"><h3>Clothing / separate fit model</h3><p>Garment size and chest/length measurements.<br>Racket grip and length do not apply.</p></div></div>{a('attribute-model','Try the category attribute switch '+ic('ArrowRight'),'textlink')}</div></section></main>''','Technical facts and explicit unknown compatibility; equipment and clothing attribute models are distinct.')
add('06-product-continuation','Keep your court kit simple','/products/rally-68 (continuation)',header()+context()+f'''<main><section class="section"><div class="wrap related"><div class="large-context">{img('activity','A recreational badminton game in daylight')}<p>Context image · Racket sold individually. Other equipment shown is not included.</p></div><div><div class="eyebrow">BEFORE YOU FINISH</div><h1>Keep your<br>court kit simple.</h1><p>These are independent products, with their own price and availability. Nothing is added automatically.</p>{''.join(f'<article class="pick">{img(p["image"],p["name"])}<div><h3>{p["name"]}</h3><p>{p["facts"][0]} · {p["price"]}</p></div>{a("product-"+p["image"],ic("ArrowUpRight"))}</article>'for p in products[1:])}{notice('Sleeve exterior: 72 × 24 cm. Internal opening is not supplied, so fit with this racket remains unconfirmed.','warning')}</div></div></section><section class="section rule"><div class="wrap"><div class="sectionhead"><h2>A few useful things to know.</h2><p>Read the supplied conditions and policy before buying.</p></div><div class="policygrid"><article class="panel"><h3>Included & care</h3><p>1 strung Rally 68 racket. Shuttles and sleeve sold separately. Wipe dry after use; store indoors and avoid prolonged heat.</p></article><article class="panel"><h3>Shipping & returns</h3><p>Shipping options appear after your address is checked. No delivery date is promised here. Review the merchant’s returns terms before ordering.</p></article><article class="panel"><h3>Questions & feedback</h3><p>No customer reviews yet. Ask about an absent measurement or condition before choosing. Do not infer compatibility from an image.</p></article></div><div style="margin-top:28px">{btn('04-product-main','Return to Rally 68 '+ic('ArrowRight'))}</div></div></section></main>'''+footer(),'Further evaluation, independent related products, missing fit fact, care/policy and honest no-reviews state.')
add('07-cart','Your cart / Ready for court time','/cart',header()+crumb('Your cart')+f'''<main class="wrap section" style="padding-top:3px"><div class="pagetitle"><div><div class="eyebrow">TRAILMARK / YOUR SELECTION</div><h1>Ready for court time.</h1></div>{a('03-collection','Continue shopping '+ic('ArrowRight'),'textlink')}</div><div class="cart-grid"><div><article class="cart-line">{img('racket','Rally 68 Forest grip 84 mm')}<div><h3>Rally 68 badminton racket</h3><p>Forest / Grip circumference 84 mm</p><p>68 cm · 88 g unstrung · ₹2,490 each</p><div class="line-controls">{quantity()}<button class="remove">Remove</button></div></div><span class="line-price">₹2,490</span></article><article class="cart-line">{img('shuttles','Court Nylon 3 shuttles')}<div><h3>Court Nylon 3 shuttles</h3><p>3 pieces per tube / White</p><p>2 tubes · 6 shuttles total · ₹490 each</p><div class="line-controls">{quantity(2)}<button class="remove">Remove</button></div></div><span class="line-price">₹980</span></article>{notice('Could not update the quantity. Your last confirmed cart is shown. Retry keeps your selected variant and avoids adding it twice.','error','RotateCcw')}<button class="textlink" data-demo-message>Retry update {ic('RotateCcw')}</button><p class="small" style="margin-top:22px">Prices and stock are checked again before checkout. Equipment options stay attached to each line.</p></div>{summary()}</div></main>'''+footer(),'Selected variant, quantity/removal and last-confirmed-cart recovery; ₹2,490 + 2 × ₹490 = ₹3,470.')
add('08-checkout-address','Shared checkout / Contact & delivery','checkout.letbuyy.com / contact-delivery',checkheader()+f'''<main class="checkout-shell checkout-grid"><section class="checkout-main">{steps()}<h1>Where should your gear go?</h1><p>Check your contact and delivery details before choosing shipping.</p><div class="form-title"><h2>Contact</h2>{a('10-sign-in','Sign in with LetBuyy')}</div><div class="form-grid">{field('Email','demo.buyer@example.test',True,kind='email')}</div><label class="checkline"><input type="checkbox">Email me optional shop news. You can order without opting in.</label><div class="form-title"><h2>Delivery address</h2></div><div class="form-grid">{field('Full name','Demo Buyer',True)}{field('Address','14 Sample Lane',True)}{field('Apartment / landmark','',True,placeholder='Optional')}{field('City','Bengaluru')}{field('PIN code','560001')}{field('State','Karnataka')}{field('Country','India')}{field('Mobile number','',True,placeholder='10-digit mobile number')}</div><div class="form-title"><h2>Shipping</h2><span class="badge">Mock quote</span></div><label class="rate"><input type="radio" checked name="shipping"><div><b>Standard shipping</b><p>Fixture rate for this address. Delivery estimate unavailable.</p></div><strong>₹90</strong></label><div class="form-actions">{btn('09-checkout-review','Continue to review '+ic('ArrowRight'))}{a('07-cart','Back to cart','textlink')}</div><div class="prototype-note">Visual prototype · Fictional contact/address and mock shipping quote. No address is submitted.</div></section><div class="checkout-side">{summary(True)}{notice('Your selected equipment options are retained through checkout. The server confirms final prices and eligibility.','','CheckCircle2')}</div></main>''','Canonical checkout address/contact/shipping fixture; no independent Trailmark checkout authority.')
add('09-checkout-review','Shared checkout / Review & pay','checkout.letbuyy.com / review-pay',checkheader()+f'''<main class="checkout-shell checkout-grid review-checkout"><section class="checkout-main">{steps(True)}<h1>One last look.</h1><p>Review your gear, address and total before you commit.</p><div class="review-block"><div class="row"><div><b>Contact</b><p>demo.buyer@example.test</p></div>{a('08-checkout-address','Edit')}</div><div class="row"><div><b>Deliver to</b><p>Demo Buyer · 14 Sample Lane<br>Bengaluru, Karnataka 560001 · India</p></div>{a('08-checkout-address','Edit')}</div><div class="row"><div><b>Shipping</b><p>Standard · ₹90<br>No delivery estimate supplied</p></div>{a('08-checkout-address','Edit')}</div></div><div class="form-title"><h2>Payment method</h2><span class="badge warning">Mock provider</span></div><label class="payment selected"><input type="radio" name="payment" checked><div><b>UPI / cards / netbanking</b><p>Continue to the merchant’s payment provider. Available methods are confirmed there.</p></div>{ic('CreditCard')}</label><label class="payment"><input type="radio" name="payment"><div><b>Cash on delivery</b><p>Eligible for this fixture address. Pay ₹3,560 on delivery.</p></div>{ic('Package')}</label>{notice('<strong>Payment could not start.</strong><br>No confirmed payment is shown. Your order details are retained. Retry the same attempt after checking its status.','error','RotateCcw')}<button class="button block" data-demo-message>Retry payment · ₹3,560 {ic('ArrowRight')}</button><p class="small" style="margin-top:17px">Choosing Pay places the order under the merchant’s terms. No money moves in this visual prototype.</p><div class="form-actions">{a('08-checkout-address','Back to delivery','textlink')}</div></section><div class="checkout-side">{summary(True)}<div class="prototype-note">Selected: 1 racket / Forest / Grip 84 mm<br>2 shuttle tubes / 3 pieces each<br>₹2,490 + ₹980 + ₹90 = ₹3,560</div></div></main>''','Full pre-commit summary, eligible payment options, truthful mock mode and retry state with no false success.')
add('10-sign-in','LetBuyy buyer sign-in / Trailmark destination','canonical identity / buyer sign-in',identity('Sign in to LetBuyy',f'''<p>Use your LetBuyy buyer account to continue to Trailmark.</p><div class="field"><label for="email">Email address</label><input id="email" type="email" value="demo.buyer@example.test" autocomplete="off"></div><div class="field"><label for="password">Password</label><input id="password" type="password" placeholder="Enter your password" autocomplete="off"></div><div class="notice">{ic('LockKeyhole')}<p>Bot verification is required when enabled. This prototype does not run the challenge.</p></div>{notice('Could not sign you in. Check your email and password, then try again. Your Trailmark destination is retained.','error','RotateCcw')}{btn('12-profile','Sign in '+ic('ArrowRight'))}<div style="margin-top:17px">{a('10-sign-in','Forgot password?','textlink')}</div><div class="divider">New to LetBuyy?</div>{a('11-sign-up','Create a buyer account','textlink')}<p class="small" style="margin:22px 0 0">After signing in, explicitly choose Continue to Trailmark. You may use a different account before continuing. No merchant or operator access is granted.</p>'''),'Current canonical buyer email/password sign-in; sole issuer, bot-check boundary and explicit named destination/continuation.')
add('11-sign-up','Create account / Continue to Trailmark','canonical identity / buyer register and signed-in continuation states',identity('Create your LetBuyy account',f'''<p>One buyer account for Trailmark and participating LetBuyy shops.</p><div class="field"><label for="new-email">Email address</label><input id="new-email" type="email" value="demo.buyer@example.test" autocomplete="off"></div><div class="field"><label for="new-password">Password</label><input id="new-password" type="password" placeholder="Create a password" autocomplete="off"><span class="help">At least 8 characters.</span></div><div class="notice">{ic('LockKeyhole')}<p>Bot verification is required when configured; the real challenge belongs to canonical identity.</p></div><button class="button block" data-demo-message>Create account</button><div style="margin-top:15px">{a('10-sign-in','Already have an account? Sign in','textlink')}</div><div class="divider">Next state / after successful account creation</div><h2 style="font-size:25px">Continue to Trailmark</h2><p style="margin-top:16px">You’re signed in to LetBuyy as <strong>demo.buyer@example.test</strong>. Trailmark will receive your email address.</p>{btn('12-profile','Continue to Trailmark '+ic('ArrowRight'))}<div style="margin-top:12px">{a('10-sign-in','Use a different account','button secondary block')}</div><p class="small" style="margin:22px 0 0">Continuing starts the canonical authorization redirect. Any separate email verification uses LetBuyy’s existing verification flow; it is not an automatic next step here. No account is created by this prototype.</p>''',True),'Current email/password registration with an8-character minimum and configured bot check, then explicit signed-in Continue to Trailmark; OAuth authorization is separate from email verification.')

profile=f'''<div class="notice success">{ic('CheckCircle2')}<p>Profile details saved. This is a fictional saved-state illustration.</p></div><section class="panel"><div class="panel-head"><h2>Your details</h2><span class="badge">LetBuyy buyer</span></div><div class="form-grid">{field('Display name','Demo Buyer',True)}{field('Email address','demo.buyer@example.test',True,readonly=True)}</div><p class="small" style="margin-top:18px">Email changes require verification through LetBuyy. Store-specific consent remains separate.</p><div class="form-actions"><button class="button" data-demo-message>Save name</button>{a('10-sign-in','Manage sign-in','textlink')}</div></section><div class="account-cards"><section class="panel"><h3>Your Trailmark orders</h3><p>1 order in this shop. View its equipment options and status.</p>{a('13-orders','View order history '+ic('ArrowRight'),'textlink')}</section><section class="panel"><h3>Saved addresses</h3><p>2 fictional addresses. Your default is used only when you choose it.</p>{a('15-addresses','Manage addresses '+ic('ArrowRight'),'textlink')}</section></div><section class="panel"><h3>Shop contact preferences</h3><p>No Trailmark marketing opt-in is recorded in this fixture. You can shop without joining marketing. Any future preference control must use the canonical scoped consent contract.</p></section>'''
add('12-profile','Your Trailmark account','/account',account('Good to see you, Demo.','Your details, addresses and Trailmark orders in one place.',profile),'Storefront identity with editable supported profile fields, canonical sign-in management and scoped consent.')
